  it('error still propagates after onError hook', async () => {
    const hooks: OrchestratorHooks = {
      onError: async () => {},
    };

    const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
      hooks,
    });
    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow('boom');
  });

  it('wraps a non-Error rejection in Error with cause and passes it to onError, while caller receives the original', async () => {
    const rejection = 'provider said no';
    let capturedError: Error | undefined;

    const nonErrorProvider: AIProvider = {
      // eslint-disable-next-line require-yield
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        throw rejection;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(nonErrorProvider, promptBuilder, undefined, {
      hooks: {
        onError: async (_session, error) => {
          capturedError = error;
        },
      },
    });

    const callerRejection = await orchestrator.processMessage(createSession('hi')).then(
      () => undefined,
      v => v
    );

    expect(capturedError).toBeInstanceOf(Error);
    expect(capturedError?.cause).toBe(rejection);
    expect(callerRejection).toBe(rejection);
  });
});

