1	#!/usr/bin/env node
2	// Re-points specs' [validated by](../../src/X.test.ts#Lnn) anchors after
3	// edits to the cited file - any cited
4	// repository file, whatever its kind: each anchor's line number is
5	// resolved to the content it cited in the base ref's copy of that file,
6	// that content is found in the working copy (compared with quotes and
7	// whitespace dropped, so a formatter pass is not drift), and the anchor is
8	// rewritten to the match whose surrounding lines agree with the baseline's. When the cited
9	// content occurs on several working lines, each candidate is scored by how
10	// many of the baseline's neighbouring lines it reproduces at the same offsets;
11	// a candidate whose context uniquely wins is chosen, and a tie is reported as
12	// ambiguous for manual fix (exit 1 in both modes) instead of guessing. An
13	// anchor into a file built of repeated blocks - a workflow whose jobs share an
14	// identical setup - must therefore cite a line unique to its own step, because
15	// the resolver refuses to guess between indistinguishable candidates.
16	//
17	// Usage:
18	//   node scripts/repoint-spec-anchors.mjs [--check] [base-ref]
19	//
20	// base-ref defaults to origin/main and must be the baseline the anchors were
21	// last correct against. Baseline line numbers are read from the base ref's
22	// copy of each spec, never from the working copy, so re-running against the
23	// same baseline is a no-op instead of a second translation. A spec whose
24	// anchor set (the ordered list of test paths it cites) differs from the base
25	// ref is skipped whole: its anchors were authored against the working tree,
26	// and no baseline exists to repoint them from. An individual anchor whose
27	// line number differs from the base spec's at the same position was
28	// deliberately retargeted by a spec edit: it is accepted as authored, never
29	// rewritten, and reported as "retargeted (not checked)".
30	//
31	// Independent of any baseline, every anchor must land on a line that exists
32	// and carries content: an anchor whose target file is missing, whose line is
33	// beyond the end of the file, or whose line is blank or closing punctuation
34	// is reported as rotten and fails the run in both modes. An anchor
35	// into a test file must additionally land on the it/test/describe declaration
36	// itself, because a line inside a test body names no case a reader can check.
37	// Non-test targets - a workflow, a config, package.json - are exempt from that
38	// last check: they have no declaration to land on.
39	//
40	// Also independent of any baseline, a short-form [Lnnn](...#Lmmm) label must
41	// name the line its own href points at. Labels are re-synced to their href
42	// after the anchor rewrite, so a repointed href carries its label with it;
43	// --check reports label/href disagreement as mislabelled and fails.
44	// --check rewrites nothing, so it judges each label against its current
45	// (un-repointed) href: a stale href is reported as stale, and once a plain run
46	// repoints it the label follows, so the two runs still converge in one pass.
47	//
48	// --check rewrites nothing and exits 1 when any anchor is stale (its baseline
49	// content now lives on a different line), unresolved (that content no
50	// longer exists), rotten, or mislabelled. Without --check, stale anchors are
51	// rewritten in place, labels are synced, and unresolved or rotten ones are
52	// reported for manual fix with exit 1; a rotten anchor the rewrite itself
53	// repoints needs no manual fix and is not reported.
54	
55	import { execFileSync } from "node:child_process";
56	import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
57	import { dirname, join, normalize } from "node:path";
58	import process from "node:process";
59	import { splitArgs } from "./lib/cli-args.mjs";
60	
61	const TRACKED_PATH = String.raw`(?:\.\.\/)+(?:scripts\/[\w./-]+|[\w./-]+\.[A-Za-z]+)`;
62	const ANCHOR = new RegExp(String.raw`(${TRACKED_PATH})#L(\d+)`, "g");
63	
64	// A short-form [Lnnn](../../src/X.test.ts#Lmmm) link: its visible label is a
65	// bare line number that must equal the href's #L number. The label has no
66	// meaning apart from the href, so it is force-synced to the href even when the
67	// href was manually retargeted; descriptive labels ([validated by], ...) never
68	// match and are never touched.
69	const LABEL_LINK = new RegExp(String.raw`\[L(\d+)\]\((${TRACKED_PATH})#L(\d+)\)`, "g");
70	
71	const { flags, positional } = splitArgs(process.argv.slice(2));
72	
73	if (flags.some((flag) => flag !== "--check") || positional.length > 1) {
74	  process.stderr.write("usage: repoint-spec-anchors.mjs [--check] [base-ref]\n");
75	  process.exit(2);
76	}
77	const checkMode = flags.includes("--check");
78	const baseRef = positional[0] ?? "origin/main";
79	
80	const root = process.cwd();
81	
82	const refResolves = () => {
83	  try {
84	    execFileSync("git", ["rev-parse", "--verify", "--quiet", `${baseRef}^{commit}`], {
85	      cwd: root,
86	      stdio: "ignore",
87	    });
88	
89	    return true;
90	  } catch {
91	    return false;
92	  }
93	};
94	
95	if (!refResolves()) {
96	  process.stderr.write(`base ref does not resolve to a commit: ${baseRef}\n`);
97	  process.exit(2);
98	}
99	
100	const readBaseFile = (path) => {
101	  try {
102	    return execFileSync("git", ["show", `${baseRef}:${path}`], {
103	      cwd: root,
104	      encoding: "utf8",
105	      stdio: ["ignore", "pipe", "ignore"],
106	    });
107	  } catch {
108	    return null;
109	  }
110	};
111	
112	const baseFileCache = new Map();
113	const baseFile = (path) => {
114	  if (!baseFileCache.has(path)) {
115	    baseFileCache.set(path, readBaseFile(path));
116	  }
117	
118	  return baseFileCache.get(path);
119	};
120	
121	const workingFileCache = new Map();
122	const workingFile = (path) => {
123	  if (workingFileCache.has(path)) {
124	    return workingFileCache.get(path);
125	  }
126	  const fullPath = join(root, path);
127	  const content = existsSync(fullPath) ? readFileSync(fullPath, "utf8") : null;
128	
129	  workingFileCache.set(path, content);
130	
131	  return content;
132	};
133	
134	const extractAnchors = (source) =>
135	  [...source.matchAll(ANCHOR)].map((match) => ({ path: match[1], line: Number(match[2]) }));
136	
137	const CONTENTLESS = /^[)\]}>,;]*$/;
138	
139	// Only test files are held to the declaration check below; a citation into a
140	// workflow, a config or package.json is a supported target with no such shape.
141	const TEST_FILE = /\.(?:test|spec)\.[cm]?[jt]sx?$/;
142	const TEST_DECL = /^\s*(?:[fx]?it|[fx]?describe|test)\s*[.(`]/;
143	
144	const rottenReason = (anchor, specDir) => {
145	  const testPath = normalize(join(specDir, anchor.path));
146	  const working = workingFile(testPath);
147	
148	  if (working === null) {
149	    return `${testPath} does not exist in the working tree`;
150	  }
151	  const target = working.split("\n")[anchor.line - 1];
152	
153	  if (target === undefined) {
154	    return `#L${anchor.line} is beyond the end of ${testPath}`;
155	  }
156	
157	  if (CONTENTLESS.test(target.trim())) {
158	    return `#L${anchor.line} lands on a blank or closing line`;
159	  }
160	
161	  if (TEST_FILE.test(testPath) && !TEST_DECL.test(target)) {
162	    return `#L${anchor.line} is not an it/test/describe declaration in ${testPath}`;
163	  }
164	
165	  return null;
166	};
167	
168	const sameAnchorPaths = (a, b) =>
169	  a.length === b.length && a.every((anchor, index) => anchor.path === b[index].path);
170	
171	const CONTEXT_RADIUS = 4;
172	
173	const contextScore = (baseLines, workingLines, baselineLine, candidateLine) => {
174	  let score = 0;
175	
176	  for (let offset = -CONTEXT_RADIUS; offset <= CONTEXT_RADIUS; offset += 1) {
177	    if (offset === 0) {
178	      continue;
179	    }
180	
181	    if (shape(baseLines[baselineLine - 1 + offset]) === shape(workingLines[candidateLine - 1 + offset])) {
182	      score += 1;
183	    }
184	  }
185	
186	  return score;
187	};
188	
189	// Lines are compared by shape, not text: a formatter changes quotes and
190	// spacing without moving anything, and that must not read as drift. An
191	// out-of-range line stays undefined so it never matches a real one.
192	const shape = (line) =>
193	  line === undefined ? undefined : line.replace(/["`]/g, "'").replace(/\s+/g, "");
194	
195	// Resolves one anchor: the content its baseline line held at the base ref,
196	// located in the working copy of the same test file. Duplicate matches are
197	// disambiguated by surrounding context; a context tie is a failure, never a
198	// guess. Returns { expectedLine } or { failure } with the reason a manual
199	// fix is needed.
200	const resolveAnchor = (anchor, baselineLine, specDir) => {
201	  const testPath = normalize(join(specDir, anchor.path));
202	  const base = baseFile(testPath);
203	
204	  if (base === null) {
205	    return { failure: `${testPath} does not exist at ${baseRef}` };
206	  }
207	  const working = workingFile(testPath);
208	
209	  if (working === null) {
210	    return { failure: `${testPath} does not exist in the working tree` };
211	  }
212	  const baseLines = base.split("\n");
213	  const workingLines = working.split("\n");
214	  const target = baseLines[baselineLine - 1];
215	
216	  if (target === undefined) {
217	    return { failure: `#L${baselineLine} is beyond the end of ${testPath} at ${baseRef}` };
218	  }
219	  const wanted = shape(target);
220	  const candidates = workingLines.flatMap((line, index) => (shape(line) === wanted ? [index + 1] : []));
221	
222	  if (candidates.length === 0) {
223	    return { failure: `"${target.trim().slice(0, 70)}" no longer exists in ${testPath}` };
224	  }
225	
226	  if (candidates.length === 1) {
227	    return { expectedLine: candidates[0] };
228	  }
229	  const scores = candidates.map((candidate) =>
230	    contextScore(baseLines, workingLines, baselineLine, candidate)
231	  );
232	  const bestScore = Math.max(...scores);
233	  const best = candidates.filter((_, index) => scores[index] === bestScore);
234	
235	  if (best.length > 1) {
236	    return {
237	      failure: `"${target.trim().slice(0, 70)}" matches ambiguously at lines ${best.join(", ")} of ${testPath}`,
238	    };
239	  }
240	
241	  return { expectedLine: best[0] };
242	};
243	
244	const specFiles = [
245	  ...readdirSync(join(root, "specs"), { withFileTypes: true })
246	    .filter((entry) => entry.isDirectory())
247	    .map((entry) => `specs/${entry.name}/spec.md`)
248	    .sort(),
249	  ".specify/spec.md",
250	].filter((spec) => existsSync(join(root, spec)));
251	
252	let moved = 0;
253	let upToDate = 0;
254	let retargeted = 0;
255	const unresolved = [];
256	const staleDetails = [];
257	const rotten = [];
258	const specContent = new Map();
259	
260	for (const spec of specFiles) {
261	  const source = readFileSync(join(root, spec), "utf8");
262	
263	  specContent.set(spec, source);
264	  const anchors = extractAnchors(source);
265	
266	  if (anchors.length === 0) {
267	    continue;
268	  }
269	  const specDir = dirname(spec);
270	  const rottenReasons = anchors.map((anchor) => rottenReason(anchor, specDir));
271	  const reportRotten = (index) => {
272	    const reason = rottenReasons[index];
273	
274	    if (reason === null) {
275	      return;
276	    }
277	    const anchor = anchors[index];
278	
279	    rotten.push(`${spec}: ${anchor.path}#L${anchor.line} -> ${reason}`);
280	  };
281	  const baseSpec = baseFile(spec);
282	
283	  if (baseSpec === null) {
284	    process.stderr.write(`skipped ${spec}: not present at ${baseRef}\n`);
285	    anchors.forEach((_, index) => reportRotten(index));
286	    continue;
287	  }
288	  const baseAnchors = extractAnchors(baseSpec);
289	
290	  if (!sameAnchorPaths(anchors, baseAnchors)) {
291	    process.stderr.write(
292	      `skipped ${spec}: anchor set differs from ${baseRef} (anchors are taken as authored against the working tree)\n`
293	    );
294	    anchors.forEach((_, index) => reportRotten(index));
295	    continue;
296	  }
297	  const resolutions = anchors.map((anchor, index) => {
298	    if (anchor.line !== baseAnchors[index].line) {
299	      return { retargeted: true };
300	    }
301	
302	    return resolveAnchor(anchor, baseAnchors[index].line, specDir);
303	  });
304	
305	  resolutions.forEach((resolution, index) => {
306	    const anchor = anchors[index];
307	    const staysPut =
308	      resolution.retargeted || resolution.failure || resolution.expectedLine === anchor.line;
309	
310	    if (checkMode || staysPut) {
311	      reportRotten(index);
312	    }
313	
314	    if (resolution.retargeted) {
315	      retargeted += 1;
316	      upToDate += 1;
317	
318	      return;
319	    }
320	
321	    if (resolution.failure) {
322	      unresolved.push(`${spec}: ${anchor.path}#L${anchor.line} -> ${resolution.failure}`);
323	
324	      return;
325	    }
326	
327	    if (resolution.expectedLine === anchor.line) {
328	      upToDate += 1;
329	
330	      return;
331	    }
332	    moved += 1;
333	    staleDetails.push(`${spec}: ${anchor.path}#L${anchor.line} -> #L${resolution.expectedLine}`);
334	  });
335	
336	  if (checkMode) {
337	    continue;
338	  }
339	  let occurrence = -1;
340	  const rewritten = source.replace(ANCHOR, (whole, relPath) => {
341	    occurrence += 1;
342	    const resolution = resolutions[occurrence];
343	
344	    if (
345	      resolution.retargeted ||
346	      resolution.failure ||
347	      resolution.expectedLine === anchors[occurrence].line
348	    ) {
349	      return whole;
350	    }
351	
352	    return `${relPath}#L${resolution.expectedLine}`;
353	  });
354	
355	  specContent.set(spec, rewritten);
356	
357	  if (rewritten !== source) {
358	    writeFileSync(join(root, spec), rewritten);
359	  }
360	}
361	
362	// Short-form labels are synced independently of the baseline: a label must
363	// agree with its own href regardless of whether that href moved. This reads
364	// the in-memory content the href rewrite above produced, so a label follows a
365	// freshly repointed href without re-reading the file from disk.
366	let relabelled = 0;
367	const mislabelled = [];
368	
369	for (const spec of specFiles) {
370	  const source = specContent.get(spec);
371	  const rewritten = source.replace(LABEL_LINK, (whole, labelLine, relPath, hrefLine) => {
372	    if (labelLine === hrefLine) {
373	      return whole;
374	    }
375	
376	    if (checkMode) {
377	      mislabelled.push(`${spec}: ${relPath}#L${hrefLine} -> label reads L${labelLine}`);
378	
379	      return whole;
380	    }
381	    relabelled += 1;
382	
383	    return `[L${hrefLine}](${relPath}#L${hrefLine})`;
384	  });
385	
386	  if (!checkMode && rewritten !== source) {
387	    writeFileSync(join(root, spec), rewritten);
388	  }
389	}
390	
391	const movedLabel = checkMode ? "stale" : "repointed";
392	const relabelledLabel = checkMode ? "mislabelled" : "relabelled";
393	const labelCount = checkMode ? mislabelled.length : relabelled;
394	
395	process.stdout.write(
396	  `${movedLabel}: ${moved}, up to date: ${upToDate}, unresolved: ${unresolved.length}, ${relabelledLabel}: ${labelCount}\n`
397	);
